import{_ as a,o,c as l,ag as t}from"./chunks/framework.DzGOF12C.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"club/MIRO/0509_MIRO_ComputerArchitecture.md","filePath":"club/MIRO/0509_MIRO_ComputerArchitecture.md"}'),e={name:"club/MIRO/0509_MIRO_ComputerArchitecture.md"};function i(n,r,s,h,p,g){return o(),l("div",null,[...r[0]||(r[0]=[t('<h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><ol><li>컴퓨터가 어떤 식으로 작동하는지에 대한 대략적인 이해</li><li>어떻게 발전했는가?</li><li>어떤 문제가 있었나? <ul><li>power wall, memory wall</li></ul></li><li>해결방안 <ul><li>HBM, PIM</li></ul></li></ol><h2 id="_1-컴퓨터의-기본-구조" tabindex="-1">1. 컴퓨터의 기본 구조 <a class="header-anchor" href="#_1-컴퓨터의-기본-구조" aria-label="Permalink to &quot;1. 컴퓨터의 기본 구조&quot;">​</a></h2><p>![[MIRO_VonNeumannArchi.png]]</p><p>“계산하는 곳(연산 장치)과 기억하는 곳(메모리 장치)이 물리적으로 떨어져 있다”</p><ul><li><strong>CPU/GPU :</strong> 계산 담당</li><li><strong>메모리 :</strong> 작업 공간</li><li><strong>버스 :</strong> 통로</li></ul><p>컴퓨터가 어떤 작업을 할 때:<br> [ 메모리에서 데이터를 꺼내 → 버스를 지나 → CPU에서 계산 ]<br> 과정을 1초에도 수십억 번씩 반복</p><p>반도체 -&gt; 트렌지스터 -&gt; 논리 게이트 -&gt; 낸드 플래시(SSD, USB, 스마트폰), 레지스터, ALU...</p><h2 id="_1-2-어디서-들어본-장치들" tabindex="-1">1-2. 어디서 들어본 장치들 <a class="header-anchor" href="#_1-2-어디서-들어본-장치들" aria-label="Permalink to &quot;1-2. 어디서 들어본 장치들&quot;">​</a></h2><h3 id="_1-레지스터-register" tabindex="-1"><strong>1. 레지스터 (Register)</strong> <a class="header-anchor" href="#_1-레지스터-register" aria-label="Permalink to &quot;**1. 레지스터 (Register)**&quot;">​</a></h3><p>레지스터가 있어서 연산도중에도 다른 데이터를 들고 올 수 있음</p><ul><li><strong>물리적 위치:</strong> CPU 내부 (ALU 인접)</li><li><strong>작동 속도:</strong> CPU 클럭 사이클과 동기화 (레이턴시 1사이클 미만)</li><li><strong>기능:</strong> 술·논리 연산의 피연산자 및 결과물, 다음 실행 명령어 주소(PC), 상태 정보(Status)의 실시간 저장</li></ul><h3 id="_2-캐시-메모리-cache-sram" tabindex="-1"><strong>2. 캐시 메모리 (Cache / SRAM)</strong> <a class="header-anchor" href="#_2-캐시-메모리-cache-sram" aria-label="Permalink to &quot;**2. 캐시 메모리 (Cache / SRAM)**&quot;">​</a></h3><p>자주 쓰는 데이터를 미리 CPU에 옮겨둠</p><ul><li><strong>물리적 위치:</strong> CPU 칩 내부</li><li><strong>기능:</strong> 참조 국부성에 기반하여 DRAM의 데이터를 복사본으로 보유, CPU와 메모리 간의 속도 차이(Memory Wall) 완화</li><li><strong>관계:</strong> 모든 SRAM이 캐시는 아니지만, <strong>대부분의 CPU 캐시는 SRAM으로 제작</strong>됨.</li></ul><h3 id="_3-주기억장치-main-memory-dram" tabindex="-1"><strong>3. 주기억장치 (Main Memory / DRAM)</strong> <a class="header-anchor" href="#_3-주기억장치-main-memory-dram" aria-label="Permalink to &quot;**3. 주기억장치 (Main Memory / DRAM)**&quot;">​</a></h3><p>CPU가 직접 소통하는 장치<br> 보조기억장치는 CPU에 비해 속도가 느려서 필요함<br> 낸드 플래시는 열에 영향을 많이 받음. SSD는 CPU의 발열에 취약</p><ul><li><strong>물리적 위치:</strong> CPU 외부 메인보드 슬롯 (메모리 버스 연결)</li><li><strong>데이터 성격:</strong> 휘발성, 전원 차단 시 전하 방전으로 데이터 소실</li><li><strong>기능:</strong> 실행 중인 프로세스의 코드 영역, 데이터 영역, 힙(Heap), 스택(Stack) 상주 공간</li></ul><h3 id="_4-보조기억장치-secondary-storage-ssd·hdd" tabindex="-1"><strong>4. 보조기억장치 (Secondary Storage / SSD·HDD)</strong> <a class="header-anchor" href="#_4-보조기억장치-secondary-storage-ssd·hdd" aria-label="Permalink to &quot;**4. 보조기억장치 (Secondary Storage / SSD·HDD)**&quot;">​</a></h3><p>CPU가 직접 접근하지 못함</p><ul><li><strong>물리적 위치:</strong> 인터페이스를 통한 외부 연결</li><li><strong>소자 특성:</strong> NAND Flash (SSD) / 자기 디스크 (HDD)</li><li><strong>데이터 성격:</strong> 비휘발성, 플로팅 게이트나 자성체를 이용한 데이터 영구 보존</li><li><strong>기능:</strong> 파일 시스템 기반의 데이터 저장, 운영체제(OS) 커널 이미지 및 응용 프로그램 설치 파일 보관</li></ul><h3 id="중간-정리" tabindex="-1">중간 정리 <a class="header-anchor" href="#중간-정리" aria-label="Permalink to &quot;중간 정리&quot;">​</a></h3><p>CPU-셰프 / DRAM - 준비된 재료 / SSD,HDD - 냉장고<br> 캐시 - 자주 쓰는 재료 / 레지스터 - 도마, 웍..</p><p>![[MIRO_cooking.png]]</p><p>GPU - 작은 크기의 ALU(연산 장치)가 여러개, (Control Unit) 간소화</p><h2 id="_2-어떻게-빨라지고-있었나" tabindex="-1">2. 어떻게 빨라지고 있었나? <a class="header-anchor" href="#_2-어떻게-빨라지고-있었나" aria-label="Permalink to &quot;2. 어떻게 빨라지고 있었나?&quot;">​</a></h2><hr><p>트렌지스터를 작게 만든다!</p><p>트렌지스터:<br> &quot;<strong>전기 신호를 주면 켜지거나 꺼지는 미세한 스위치이며, 모든 디지털 논리를 실현하는 최소 단위</strong>&quot;</p><p>반도체 -&gt; 트렌지스터 -&gt; 논리 게이트 -&gt; 낸드 플래시(SSD, USB, 스마트폰), 레지스터, ALU...</p><p>트렌지스터 소형화의 이점</p><ol><li>같은 공간에서 더 많은 일을 할 수 있게 된다! (더 많은 코어, 더 큰 캐시)</li><li>작아지니까 사용하는 전력소비도 줄어든다!</li><li>전력소비가 줄어드니 트렌지스터당 발열도 줄어든다!</li></ol><p>소형화의 제약</p><ol><li>트렌지스터가 작아지면서 사이의 벽이 얇아저 전자가 통과해버림</li><li>필요한 전압이 낮아지면서 열에너지 때문에 날뛰는 전자로 인해 흐르게 됨</li></ol><h2 id="_3-문제점" tabindex="-1">3. 문제점 <a class="header-anchor" href="#_3-문제점" aria-label="Permalink to &quot;3. 문제점&quot;">​</a></h2><hr><h3 id="_1-power-wall-전력-발열-문제" tabindex="-1">1. power wall (전력, 발열 문제) <a class="header-anchor" href="#_1-power-wall-전력-발열-문제" aria-label="Permalink to &quot;1. power wall (전력, 발열 문제)&quot;">​</a></h3><p>컴퓨터를 더 빨리 돌리기 위해 발생하는 추가적인 전력 소모를 트랜지스터 크기를 줄여서 버텨왔는데, 더이상 트랜지스터를 작게 만들수 없게 되었다!</p><p>![[Intel_x86_ClockRate_Power_Trend.png|580]]</p><p>![[MIRO_CPU.png|586]]<br> - 마이크로프로세서 트렌드데이터</p><p><strong>클록 주파수 (초록색 네모)</strong><br> 2000년대 중반부터 수평을 유지</p><ul><li>&#39;전력 장벽(Power Wall)&#39;에 부딪힌 지점</li><li>칩이 너무 뜨거워져서 더 이상 속도를 높이기 어려워진 상태</li></ul><p><strong>-&gt; 멀티코어로 해결</strong><br> cpu 1개로 빠르게 돌리니까 너무 뜨거워지네?<br> cpu 2개 쓸래</p><h3 id="_2-병목-현상-느린-버스-메모리-속도" tabindex="-1">2. 병목 현상 (느린 버스, 메모리 속도) <a class="header-anchor" href="#_2-병목-현상-느린-버스-메모리-속도" aria-label="Permalink to &quot;2. 병목 현상 (느린 버스, 메모리 속도)&quot;">​</a></h3><p>Memory Wall + Von Neumann Bottleneck</p><p>CPU는 빠른데,<br> CPU와 DRAM사이의 속도차이 + DRAM에서 CPU로 메모리를 들고오는 시간이 너무 길다!</p><p>왜 차이가 날까?</p><ul><li><strong>CPU:</strong> 트랜지스터 스위치만 바꾸면 끝</li><li><strong>DRAM:</strong> 데이터를 읽으려면 커패시터에 든 전기를 빼내야 하고, 쓰려면 다시 채워야 하는데, 트랜지스터를 아무리 줄여도 이 물리적 충전 속도를 CPU의 연산 속도만큼 올리기 힘듦</li></ul><p><strong>결국 CPU가 빨라져도 메모리 속도에 맞춰야한다!</strong></p><h2 id="_4-이후-방안" tabindex="-1">4. 이후 방안 <a class="header-anchor" href="#_4-이후-방안" aria-label="Permalink to &quot;4. 이후 방안&quot;">​</a></h2><hr><h3 id="_1-hbm-high-bandwidth-memory-고대역폭-메모리" tabindex="-1">1. HBM (High Bandwidth Memory - 고대역폭 메모리): <a class="header-anchor" href="#_1-hbm-high-bandwidth-memory-고대역폭-메모리" aria-label="Permalink to &quot;1. HBM (High Bandwidth Memory - 고대역폭 메모리):&quot;">​</a></h3><p>![[MIRO_TSV.png|688]]</p><p>DRAM과 CPU사이의 길을 늘리자!</p><p>D램을 수직으로 쌓아 올림</p><p><strong>TSV(실리콘 관통 전극)</strong>:<br> 칩에 미세한 구멍을 뚫어 전극으로 연결</p><ol><li>통로의 개수가 늘었다!</li><li>수직으로 다니니 경로가 짧아져 전력소모를 줄였다! (발열 문제)</li><li>CPU와 붙여서 지으니 거리가 짧아져 병목현상을 해결했다!</li></ol><p>SK하이닉스, 삼성전자, 마이크론</p><h3 id="_2-pim-processing-in-memory" tabindex="-1">2. PIM (Processing-In-Memory): <a class="header-anchor" href="#_2-pim-processing-in-memory" aria-label="Permalink to &quot;2. PIM (Processing-In-Memory):&quot;">​</a></h3><p>메모리에서 연산을 하자</p><p><strong>메모리 칩 내부에 아주 작은 계산기(ALU)를 직접 탑재하는 기술</strong></p>',61)])])}const u=a(e,[["render",i]]);export{c as __pageData,u as default};
